arguments.command:
python3 -c "import openpyxl; wb = openpyxl.load_workbook('gdp.xlsx'); print(wb.sheetnames); sheet = wb['Task']; print('--- Task Sheet Head ---'); row_limit=45; 
for i, row in enumerate(sheet.iter_rows(values_only=True)):
    if i > row_limit: break
    print(row)
data_sheet = wb['Data']; print('--- Data Sheet Subset ---'); 
for i, row in enumerate(data_sheet.iter_rows(min_row=21, max_row=40, values_only=True)):
    print(i+21, row)"

python3 -c "import openpyxl; wb = openpyxl.load_workbook('gdp.xlsx'); 
print('--- Data Sheet Row 20 ---');
print(list(wb['Data'].iter_rows(min_row=20, max_row=20, values_only=True))[0])
print('--- Task Sheet Rows 48-55 ---');
for row in wb['Task'].iter_rows(min_row=48, max_row=55, values_only=True):
    print(row)"

